def solve():
    digits = [0, 1, 2, 8]
    count = 0

    # Iterate over all combinations for d1, d2, d3, d4
    # d1 cannot be 0
    for d1 in [d for d in digits if d != 0]:
        for d2 in digits:
            for d3 in digits:
                for d4 in digits:
                    # Check divisibility by 3: sum of digits must be divisible by 3
                    s = d1 + d2 + d3 + d4
                    if s % 3 == 0:
                        count += 1
                        # Optional: print the number to verify
                        # print(f"{d1}{d2}{d3}{d4} (Sum: {s})")

    return count

result = solve()
print(result)
